screenViewBase::~screenViewBase()
{

}

void screenViewBase::setupScreen()
{
    transitionBegins();
}

void screenViewBase::transitionBegins()
{
    //Interaction1
    //When screen transition begins rotate textureMapper3
    //Rotate textureMapper3
    textureMapper3.setupAnimation(touchgfx::AnimationTextureMapper::X_ROTATION, 0.000f, 210, 0, touchgfx::EasingEquations::linearEaseIn);
    textureMapper3.setupAnimation(touchgfx::AnimationTextureMapper::Y_ROTATION, 0.000f, 210, 0, touchgfx::EasingEquations::linearEaseIn);
    textureMapper3.setupAnimation(touchgfx::AnimationTextureMapper::Z_ROTATION, 6.300f, 210, 0, touchgfx::EasingEquations::linearEaseIn);
    textureMapper3.startAnimation();

    //Interaction2
    //When screen transition begins scale textureMapper3
    //Scale textureMapper3
    textureMapper3.setupAnimation(touchgfx::AnimationTextureMapper::SCALE, 1.000f, 240, 0, touchgfx::EasingEquations::linearEaseIn);
    textureMapper3.startAnimation();
}

void screenViewBase::change_to_menu()
{
    //Interaction3
    //When change_to_menu is called change screen to Screen_menu
    //Go to Screen_menu with no screen transition
    application().gotoScreen_menuScreenNoTransition();
}
